// Parsing do HTML do Workana — extrai dados do atributo Vue.js results-initials
const html = ($input.first().json.data || $input.first().json || '').toString();
if (!html || html.length < 100) {
  return [{ json: { projects: [], note: 'empty_html', size: html.length } }];
}

const output = [];

const match = html.match(/:results-initials='([^']+)'/);
if (match) {
  try {
    let decoded = match[1]
      .replace(/&quot;/g, '"')
      .replace(/&amp;/g, '&')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&#039;/g, "'");

    const data = JSON.parse(decoded);
    const projects = data.results || [];

    for (const r of projects) {
      const titleRaw = r.title || '';
      const titleHtmlMatch = titleRaw.match(/title="([^"]*)"/);
      const title = titleHtmlMatch ? titleHtmlMatch[1] : titleRaw.replace(/<[^>]+>/g, '').trim();

      const linkMatch = titleRaw.match(/href="([^"]+)"/);
      let link = linkMatch ? linkMatch[1] : '';
      if (link && !link.startsWith('http')) link = 'https://www.workana.com' + link;

      const description = (r.description || r.shortDescription || '').replace(/<[^>]+>/g, '').replace(/&#039;/g, "'").replace(/&amp;/g, '&').trim();

      const skills = (r.skills || []).map(s => s.anchorText || s.name || '').filter(Boolean);

      const bidsStr = String(r.totalBids || '');
      const bidsMatch = bidsStr.match(/(\d+)/);
      const totalBids = bidsMatch ? parseInt(bidsMatch[1]) : 0;

      output.push({
        json: {
          link,
          title,
          description: description.slice(0, 500),
          budget: r.budget || '',
          deadline: r.deadline || r.deadlineValue || '',
          category: 'Programação e Tecnologia',
          skills,
          total_bids: totalBids,
          posted_date: r.postedDate || '',
          is_urgent: r.isUrgent || false,
          captured_at: new Date().toISOString()
        }
      });
    }
  } catch (e) {
    return [{ json: { projects: [], note: 'parse_error', error: e.message } }];
  }
}

const maxResults = $input.first().json.MAX_RESULTS_PER_RUN || 50;
return output.slice(0, maxResults);

// Filtra projetos pelos critérios configuráveis no nó Config.
const config = $('Config (parâmetros editáveis)').first().json;
const MIN_BUDGET = Number(config.MIN_BUDGET_USD) || 0;
const MIN_HITS = Number(config.MIN_KEYWORD_HITS) || 1;
const keywords = String(config.KEYWORDS || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const catsAllowed = String(config.CATEGORIES_ALLOWED || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);

const all = $input.all();
const kept = [];

for (const item of all) {
  const p = item.json;
  const haystack = (p.title + ' ' + p.description + ' ' + p.category + ' ' + (p.skills || []).join(' ')).toLowerCase();
  const hits = keywords.filter(k => haystack.includes(k)).length;
  const budgetNum = parseInt(String(p.budget || '').replace(/[^0-9]/g, ''), 10) || 0;
  const catOk = catsAllowed.length === 0 || catsAllowed.some(c => (p.category || '').toLowerCase().includes(c));
  if (hits >= MIN_HITS && (MIN_BUDGET === 0 || budgetNum >= MIN_BUDGET) && catOk) {
    kept.push({ json: { ...p, keyword_hits: hits, budget_num: budgetNum } });
  }
}

return kept;

// Dedup in-memory: filtra URLs já processadas nesta sessão
const inputItems = $input.all();
const config = $('Config (parâmetros editáveis)').first().json;
const alreadyProcessed = new Set((config.ALREADY_PROCESSED_URLS || '').split(',').filter(Boolean));

const fresh = inputItems.filter(item => {
  const link = item.json.link || '';
  return link && !alreadyProcessed.has(link);
});

return fresh.map(item => ({ json: item.json }));

// Formata linhas para Google Sheets
const inputItems = $input.all();
const now = new Date().toISOString().split('T')[0];

return inputItems.map(item => {
  const p = item.json;
  return {
    json: {
      Titulo: p.title || '',
      Link: p.link || '',
      Orcamento: p.budget || '',
      Publicado: p.posted_date || '',
      Urgente: p.is_urgent ? 'SIM' : 'não',
      Categoria: p.category || '',
      Keyword_Hits: p.keyword_hits || 0,
      Data_Captura: now,
      Status: 'capturado',
      Descricao: p.description || '',
      Prazo: p.Prazo || 'N/A'
    }
  };
});

