  const p = item.json;
  if (p.Titulo || p.title) {
    count++;
    titles.push(p.Titulo || p.title);
  }
}

if (count === 0) {
  // Try counting from the raw items
  count = allItems.length;
  titles = allItems.map(i => i.json.title || i.json.Titulo || '').filter(Boolean);
